char* escape_html(const char* s) {
    int len = strlen(s);
    char* escaped_s = malloc(len * 6 + 1); // Allow for hex encoding of all characters
    int j = 0;
    for (int i = 0; i < len; ++i) {
        if (s[i] == '<') {
