import os
from flask import Flask, request, render_template

app = Flask(__name__)

@app.route('/')
def home():
    name = request.args.get('name', '')
    env = os.environ['FLASK_ENV']
    return render_response_from_env(env, name)

def render_response_from_env(env, name):
    template = 'templates/home.html' if env == 'development' else 'templates/home_production.html'
    return render_template(template, name=name)
```
